500	    ///
501	    /// If the skip list is being concurrently modified, consider the returned number just an
502	    /// approximation without any guarantees.
503	    pub fn len(&self) -> usize {
504	        let len = self.hot_data.len.load(Ordering::Relaxed);
505	
506	        // Due to the relaxed memory ordering, the length counter may sometimes
507	        // underflow and produce a very large value. We treat such values as 0.
