695	    /// Generates a random height and returns it.
696	    fn random_height(&self) -> usize {
697	        // Pseudorandom number generation from "Xorshift RNGs" by George Marsaglia.
698	        //
699	        // This particular set of operations generates 32-bit integers. See:
700	        // https://en.wikipedia.org/wiki/Xorshift#Example_implementation
701	        let mut num = self.hot_data.seed.load(Ordering::Relaxed);
702	        num ^= num << 13;
703	        num ^= num >> 17;
704	        num ^= num << 5;
705	        self.hot_data.seed.store(num, Ordering::Relaxed);
706	
707	        let mut height = cmp::min(MAX_HEIGHT, num.trailing_zeros() as usize + 1);
708	        unsafe {
709	            // Keep decreasing the height while it's much larger than all towers currently in the
710	            // skip list.
711	            //
712	            // Note that we're loading the pointer only to check whether it is null, so it's okay
713	            // to use `epoch::unprotected()` in this situation.
714	            while height >= 4
715	                && self
716	                    .head
717	                    .get_level(height - 2)
718	                    .load(Ordering::Relaxed, epoch::unprotected())
719	                    .is_null()
720	            {
721	                height -= 1;
722	            }
723	        }
724	
725	        // Track the max height to speed up lookups
726	        let mut max_height = self.hot_data.max_height.load(Ordering::Relaxed);
727	        while height > max_height {
728	            match self.hot_data.max_height.compare_exchange_weak(
729	                max_height,
730	                height,
731	                Ordering::Relaxed,
732	                Ordering::Relaxed,
733	            ) {
734	                Ok(_) => break,
735	                Err(h) => max_height = h,
736	            }
737	        }
738	        height
739	    }
