771	    /// Returns the successor of a node.
772	    ///
773	    /// This will keep searching until a non-deleted node is found. If a deleted
774	    /// node is reached then a search is performed using the given key.
775	    fn next_node<'a>(
776	        &'a self,
777	        pred: TowerRef<'a, K, V>,
778	        lower_bound: Bound<&K>,
779	        guard: &'a Guard,
780	    ) -> Option<NodeRef<'a, K, V>> {
781	        unsafe {
782	            // Load the level 0 successor of the current node.
783	            let mut curr = pred.get_level(0).load_consume(guard);
784	
785	            // If `curr` is marked, that means `pred` is removed and we have to use
786	            // a key search.
787	            if curr.tag() == 1 {
788	                return self.search_bound(lower_bound, false, guard);
789	            }
790	
791	            while let Some(c) = NodeRef::from_shared(curr) {
792	                let succ = c.get_level(0).load_consume(guard);
793	
794	                if succ.tag() == 1 {
795	                    if let Some(c) = self.help_unlink(pred.get_level(0), c, succ, guard) {
796	                        // On success, continue searching through the current level.
797	                        curr = c;
798	                        continue;
799	                    } else {
800	                        // On failure, we cannot do anything reasonable to continue
801	                        // searching from the current position. Restart the search.
802	                        return self.search_bound(lower_bound, false, guard);
803	                    }
804	                }
805	
806	                return Some(c);
807	            }
808	
809	            None
810	        }
811	    }
